    while (true)
    {
      var request = server.WaitForRequest();

      Console.WriteLine($"Recieved a request: {request.Name}");

      try
      {
        if (request.Name == "getMovies")
        {
          request.Respond(database.Movies);
        }
        else if (request.Name == "getMovie")
        {
          var movieId = request.GetParams<int>();

          var movie = database.Movies.Find(movieId);

          request.Respond(movie);
        }
        else if(request.Name == "signUp")
        {
          var (username, password) = request.GetParams<(string, string)>();
          if (database.Users.Any(u => u.Username == username))
          {
            request.Respond<string?>(null);
            continue;
          } 

          var token = Guid.NewGuid().ToString();
          var user = new User(token, username, password);
          database.Users.Add(user);
          database.SaveChanges();

          request.Respond(token);

        }
        else if(request.Name == "logIn")
        {
          var (username, password) = request.GetParams<(string, string)>();
          var userDetails = database.Users.Where(u => u.Username == username).Select(u => new { u.Password, u.Token }).FirstOrDefault();

          if (userDetails == null || userDetails.Password != password)
          {
              request.Respond<string?>(null);
              continue;
          }
          request.Respond(userDetails.Token);
        }

        // else if (request.Name == "addMovie")
        // {
        //   var (movieName, imageUrl, description, type, duration, age, year, ticketPrice) = request.GetParams<(string, string, string, int, int. int, int, int)>();
        //   AddMovie(database, movieName, imageUrl, description, type, duration, age, year, ticketPrice);
        // }
      
      }
      catch (Exception exception)
      {
        request.SetStatusCode(500);
        Log.WriteException(exception);
      }
    }
    
