class Database() : DatabaseCore("database")
{
  public DbSet<Movie> Movies { get; set; } = default!;
  public DbSet<User> Users { get; set; } = default!;

  protected override void OnModelCreating(ModelBuilder modelBuilder)
  {
      base.OnModelCreating(modelBuilder);

      modelBuilder.Entity<Movie>().Property(m => m.Chairs).HasConversion(v => string.Join(',', v), v => v.Split(',', StringSplitOptions.RemoveEmptyEntries).Select(bool.Parse).ToArray());
  }
}

class Movie(string name, string imageUrl, string description, int type, int duration, int age, int year, int ticketPrice, bool[] chairs)
{
  public int Id { get; set; } = default!;
  public string Name { get; set; } = name;
  public string ImageUrl { get; set; } = imageUrl;
  public string Description { get; set; } = description;
  public int Type { get; set; } = type;
  // 1 - Hot now
  // 2 - Action
  // 3 - Comedy
  // 4 - Fantasy
  // 5 - Family
  // 6 - Horror
  public int Duration { get; set; } = duration;
  public int Age { get; set; } = age;
  public int Year { get; set; } = year;
  public int TicketPrice { get; set; } = ticketPrice;
  public bool[] Chairs { get; set; } = chairs;
}

class User(string token, string username, string password)
{
  public int Id { get; set; } = default!;
   public string Token { get; set; } = token;
  public string Username { get; set; } = username;
  public string Password { get; set; } = password;
}

